import re
import json
from argparse import ArgumentParser
from os import path, makedirs
from os.path import join
from collections import defaultdict
from pathlib import Path
from pprint import pprint
from git import Repo

parser = ArgumentParser()
parser.add_argument('--repo', '-r', help="Repo name", default="github")
parser.add_argument('--dir', '-d', help="Output directory", default="../data/patch_files")
parser.add_argument('--src', '-s', help="Source directory", default="../data/patches")
args = parser.parse_args()

def get_patch_list(repo):
    """Get all patches in a repo"""
    return [str(p) for p in repo.git.ls_tree().split('\n')]

def get_patch_files(repo, patch_list):
    """Get all patch files in a repo"""
    return [str(p) for p in repo.git.ls_tree("--full-name", "HEAD").split('\n')]

def get_buggy_lines(patch):
    """Get all buggy lines in a patch file"""
    buggy_lines = set()
    for l in patch.split('\n'):
        m = re.search("Line (\d+)", l)
        if m:
            buggy_lines.add(m.group(1))
    return list(map(int, buggy_lines))

def extract_bug_fix_patches(patch_list):
    """Extract all bug fix patches in a repo"""
    patches = {}
    for p in patch_list:
        patch_file = join(args.src, p)
        with open(patch_file) as pf:
            patch = pf.read()
        buggy_lines = get_buggy_lines(patch)
        patches[p] = buggy_lines
    return patches

def write_bug_fix_patches(patches):
    """Write all bug fix patches in a repo"""
    bug_fix_patches = defaultdict(list)
    for p, lines in patches.items():
        for l in lines:
            bug_fix_patches[l].append(p)

    for l, p in bug_fix_patches.items():
        out_file = join(args.dir, f"buggy_{l}.json")
        with open(out_file, 'w') as of:
            json.dump(p, of)

def main():
    print(f"Loading repo: {args.repo}")
    if args.repo == "github":
        repo = Repo("../repos/github")
    elif args.repo == "pypi":
        repo = Repo("../repos/pypi")
    else:
        repo = Repo("../repos/tensorflow")

